package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Create-owner step: rejects the request with a 409 when another owner already shares the
 * same {@link Household} — the same last name and address. Skipped when the request opts
 * in with {@code sharesHousehold: true}, in which case {@link AssignHousehold} instead
 * links the owners under a shared identifier. Runs after {@link ValidateOwnerFields} (so
 * the required fields are present) and before {@link BuildOwner}.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner owner : ownerRepository.findAll()) {
            if (Household.matches(owner, request.getLastName(), request.getAddress())) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}

===== AssignHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-owner step for the {@code sharesHousehold} opt-in: when the request joins an
 * existing {@link Household} (another owner with the same last name and address), assigns
 * the shared household identifier to both the new owner and every existing member, so all
 * owners in the household report the same {@code householdId}. A no-op when the request
 * does not opt in or joins no existing owner. Runs after {@link BuildOwner} and before
 * {@link SaveOwner} persists the new owner.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String householdId = Household.id(owner.getLastName(), owner.getAddress());
        boolean joined = false;
        for (Owner member : ownerRepository.findAll()) {
            if (Household.matches(member, owner.getLastName(), owner.getAddress())) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
                joined = true;
            }
        }
        if (joined) {
            owner.setHouseholdId(householdId);
        }
    }
}

===== Household.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.UUID;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "household": owners sharing the same last name and
 * address, compared case-insensitively with runs of whitespace collapsed to a single
 * space. Provides the membership test and the stable identifier shared by the household.
 *
 * <p>The identifier is derived deterministically from the normalized last name and
 * address, so every owner in the same household resolves to the same value regardless of
 * creation order.
 *
 * @see EnsureUniqueHousehold rejects a duplicate household unless the request opts in.
 * @see AssignHousehold assigns the shared identifier to the joining owners.
 */
final class Household {

    private Household() {
    }

    /** Whether {@code owner} belongs to the household keyed by {@code lastName} and {@code address}. */
    static boolean matches(Owner owner, String lastName, String address) {
        return normalize(lastName).equals(normalize(owner.getLastName()))
                && normalize(address).equals(normalize(owner.getAddress()));
    }

    /** The stable identifier shared by every owner in the household keyed by {@code lastName} and {@code address}. */
    static String id(String lastName, String address) {
        String key = normalize(lastName) + "\n" + normalize(address);
        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
    }

    /** Trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

