14	 * uses it to store the E.164 value and {@link EnsureUniqueTelephone} uses it to compare
15	 * telephones for duplicates.
16	 */
17	final class E164Telephone {
18	
19	    /** Country code assumed when the number carries no explicit '+' prefix. */
20	    private static final String DEFAULT_COUNTRY_CODE = "61";
21	
22	    private static final int MIN_DIGITS = 8;
23	
24	    private static final int MAX_DIGITS = 15;
25	
26	    private E164Telephone() {
27	    }
28	
29	    /**
30	     * Normalize {@code telephone} to E.164, or throw when it cannot form a valid number.
31	     */
32	    static String normalize(String telephone) throws InvalidTelephoneException {
33	        if (telephone == null) {
34	            throw new InvalidTelephoneException();
35	        }
36	        String trimmed = telephone.trim();
37	        boolean explicitCountryCode = trimmed.startsWith("+");
38	        String cleaned = trimmed.replaceAll("[\\s()\\-]", "");
39	        if (explicitCountryCode) {
40	            cleaned = cleaned.substring(1);
41	        }
42	        if (cleaned.isEmpty() || !cleaned.chars().allMatch(c -> c >= '0' && c <= '9')) {
43	            throw new InvalidTelephoneException();
44	        }
45	        String digits;
46	        if (explicitCountryCode) {
47	            digits = cleaned;
48	        }
49	        else {
50	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
51	            digits = DEFAULT_COUNTRY_CODE + national;
52	        }
53	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
54	            throw new InvalidTelephoneException();
55	        }
56	        return "+" + digits;
57	    }
