package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}: rejects a body that is missing or blank in any
 * required field, reporting every offending field at once. Publishes the validated body
 * for {@link BuildOwner} so the request is read only here.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        List<String> missing = new ArrayList<>();
        require("firstName", request.getFirstName(), missing);
        require("lastName", request.getLastName(), missing);
        require("address", request.getAddress(), missing);
        require("city", request.getCity(), missing);
        require("telephone", request.getTelephone(), missing);
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static void require(String name, String value, List<String> missing) {
        if (value == null || value.isBlank()) {
            missing.add(name);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.UUID;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "household": owners sharing the same last name and
 * address, compared case-insensitively with runs of whitespace collapsed to a single
 * space. Provides the membership test and the stable identifier shared by the household.
 *
 * <p>The identifier is derived deterministically from the normalized last name and
 * address, so every owner in the same household resolves to the same value regardless of
 * creation order.
 *
 * @see EnsureUniqueHousehold rejects a duplicate household unless the request opts in.
 * @see AssignHousehold assigns the shared identifier to the joining owners.
 */
final class Household {

    private Household() {
    }

    /** Whether {@code owner} belongs to the household keyed by {@code lastName} and {@code address}. */
    static boolean matches(Owner owner, String lastName, String address) {
        return normalize(lastName).equals(normalize(owner.getLastName()))
                && normalize(address).equals(normalize(owner.getAddress()));
    }

    /** The stable identifier shared by every owner in the household keyed by {@code lastName} and {@code address}. */
    static String id(String lastName, String address) {
        String key = normalize(lastName) + "\n" + normalize(address);
        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
    }

    /** Trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

